INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8779, 's8779', 'Yes or No 2', 1, '5', '2012', '2018-11-08', '112', 'min', 'No longer university girls, Kim and Pie face new hurdles in their relationship, including work, new friends and other distractions.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8780, 's8780', 'Yes or No 2.5', 1, '5', '2015', '2018-11-08', '107', 'min', 'Roommates Wine and Pie find their lives turned upside down when two more ladies move in next door, bringing up past heartaches and new attractions.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8781, 's8781', 'Yo-Kai Watch', 2, '7', '2015', '2016-04-01', '1', 'Season', 'Nate frees a mythical being trapped in a magic capsule, and the two new friends have adventures with all sorts of troublesome supernatural creatures.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8782, 's8782', 'Yo-Kai Watch: The Movie', 1, '7', '2016', '2016-12-01', '96', 'min', 'Nate''s special Yo-Kai Watch is missing. He travels back in time to meet the watch''s inventor, his grandfather. Together, they must restore history!');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8783, 's8783', 'Yoga Hosers', 1, '1', '2016', '2016-12-02', '88', 'min', 'With an all-important high school party at stake, two teen yoga fanatics enlist a man hunter to help fight an army of monsters created by Nazis.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8784, 's8784', 'Yoko', 2, '6', '2016', '2018-06-23', '1', 'Season', 'Friends Mai, Oto and Vik''s games at the park become magical adventures, thanks to Yoko, who can turn playgrounds into spaceships and camping sites.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8785, 's8785', 'Yoko and His Friends', 1, '6', '2015', '2018-06-23', '78', 'min', 'Vik meets new friends in a new city, where they go on exciting adventures together with a magical being. But soon, his family must move again.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8786, 's8786', 'YOM', 2, '7', '2016', '2018-06-07', '1', 'Season', 'With the mind of a human being, and the body of whichever animal he chooses to be, a young boy protects the world from danger.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8787, 's8787', 'You Can Tutu', 1, '9', '2017', '2017-12-31', '87', 'min', 'A gifted young ballet dancer struggles to find her footing in an uptight ballet school that brings her and her family to a brand-new neighborhood.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8788, 's8788', 'You Can’t Fight Christmas', 1, '5', '2017', '2017-12-19', '85', 'min', 'After stepping in to revitalize his family''s hotel, a money-minded businessman clashes with the hotel''s cheery, Christmas-loving decorator.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8789, 's8789', 'You Carry Me', 1, '2', '2015', '2016-07-01', '157', 'min', 'A soap opera producer, director and makeup artist each face wrenching family turmoil, from teen rebellion and marital infidelity to Alzheimer''s.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8790, 's8790', 'You Changed My Life', 1, '5', '2009', '2019-02-27', '116', 'min', 'Laida and Miggy think they''ve found perfect happiness with each other, until their burgeoning careers force them into a long-distance relationship.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8791, 's8791', 'You Don''t Mess with the Zohan', 1, '14', '2008', '2019-09-01', '113', 'min', 'An Israeli counterterrorism soldier with a secretly fabulous ambition to become a Manhattan hairstylist will do anything to make his dreams come true.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8792, 's8792', 'Young Adult', 1, '8', '2011', '2019-11-20', '94', 'min', 'When a divorced writer gets a letter from an old boyfriend announcing his wife''s had a baby, she returns to her hometown to reconnect with her ex.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8793, 's8793', 'Young Tiger', 1, '12', '1973', '2016-11-01', '81', 'min', 'Aided only by a tough female police officer, a Hong Kong taxi driver tries to escape from gangsters pursuing incriminating evidence left in his cab.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8794, 's8794', 'Yours, Mine and Ours', 1, '3', '2005', '2019-11-20', '88', 'min', 'When a father of eight and a mother of 10 prepare to wed, the couple''s children attempt to sabotage the union in this remake of a 1968 comedy.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8795, 's8795', 'اشتباك', 1, '4', '2016', '2018-10-11', '98', 'min', 'Amid the tumult following Egyptian President Morsi''s ouster, demonstrators from divergent backgrounds are brought together inside a police truck.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8796, 's8796', 'Yu-Gi-Oh! Arc-V', 2, '7', '2015', '2018-05-01', '2', 'Seasons', 'Now that he''s discovered the Pendulum Summoning technique, Yuya''s dream of becoming the greatest "dueltainer" is in reach – but it won''t be easy!');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8797, 's8797', 'Yunus Emre', 2, '5', '2016', '2017-01-17', '2', 'Seasons', 'During the Mongol invasions, Yunus Emre leaves his home to travel across the Ottoman Empire, defying hardships and temptations to become a dervish.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8798, 's8798', 'Zak Storm', 2, '7', '2016', '2018-09-13', '3', 'Seasons', 'Teen surfer Zak Storm is mysteriously transported to the Bermuda Triangle, where he becomes the captain of a magical ship full of misfits.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8799, 's8799', 'Zed Plus', 1, '2', '2014', '2019-12-31', '131', 'min', 'A philandering small-town mechanic''s political ambitions are sparked when the visiting prime minister mistakenly grants him special security clearance.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8800, 's8800', 'Zenda', 1, '4', '2009', '2018-02-15', '120', 'min', 'A change in the leadership of a political party sparks bitter conflict and the party''s division into two rival factions.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8801, 's8801', 'Zindagi Gulzar Hai', 2, '5', '2012', '2016-12-15', '1', 'Season', 'Strong-willed, middle-class Kashaf and carefree, wealthy Zaroon meet in college, but before love can take root, they each have some growing up to do.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8802, 's8802', 'Zinzana', 1, '2', '2015', '2016-03-09', '96', 'min', 'Recovering alcoholic Talal wakes up inside a small-town police station cell, where he''s subject to the mind games of a psychotic sadist.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8803, 's8803', 'Zodiac', 1, '8', '2007', '2019-11-20', '158', 'min', 'A political cartoonist, a crime reporter and a pair of cops investigate San Francisco''s infamous Zodiac Killer in this thriller based on a true story.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8804, 's8804', 'Zombie Dumb', 2, '7', '2018', '2019-07-01', '2', 'Seasons', 'While living alone in a spooky town, a young girl befriends a motley crew of zombie children with diverse personalities.');
INSERT INTO public.titulos (id_titulo, show_id_original, titulo, id_tipo_contenido, id_clasificacion, ano_lanzamiento, fecha_adicion, duracion_valor, duracion_unidad, descripcion) VALUES (8805, 's8805', 'Zombieland', 1, '8', '2009', '2019-11-01', '88', 'min', 'Looking to survive in a world taken over by zombies, a dorky college student teams with an urban roughneck and a pair of grifter sisters.');
