-- -----------------------------------------------------------------------------
-- 1. TABLAS MAESTRAS (DICCIONARIOS Y ENTIDADES BASE)
-- -----------------------------------------------------------------------------

CREATE TABLE public.tipos_contenido (
    id_tipo_contenido SERIAL PRIMARY KEY,
    nombre_tipo CHARACTER VARYING(20) NOT NULL UNIQUE,
    CONSTRAINT chk_nombre_tipo CHECK (((nombre_tipo)::text = ANY ((ARRAY['Movie'::character varying, 'TV Show'::character varying])::text[])))
);
COMMENT ON TABLE public.tipos_contenido IS 'Tabla maestra de categorías primarias de contenido (Película o Serie)';

CREATE TABLE public.clasificaciones (
    id_clasificacion SERIAL PRIMARY KEY,
    codigo_clasificacion CHARACTER VARYING(20) NOT NULL UNIQUE
);
COMMENT ON TABLE public.clasificaciones IS 'Tabla maestra con clasificaciones de público/edad (PG-13, TV-MA, R, etc.)';

CREATE TABLE public.paises (
    id_pais SERIAL PRIMARY KEY,
    nombre_pais CHARACTER VARYING(100) NOT NULL UNIQUE
);
COMMENT ON TABLE public.paises IS 'Tabla maestra de países de producción';

CREATE TABLE public.generos (
    id_genero SERIAL PRIMARY KEY,
    nombre_genero CHARACTER VARYING(100) NOT NULL UNIQUE
);
COMMENT ON TABLE public.generos IS 'Tabla maestra de géneros cinematográficos y televisivos';

CREATE TABLE public.personas (
    id_persona SERIAL PRIMARY KEY,
    nombre_persona CHARACTER VARYING(255) NOT NULL UNIQUE
);
COMMENT ON TABLE public.personas IS 'Tabla maestra de participantes (directores, actores y elenco en general)';

-- -----------------------------------------------------------------------------
-- 2. TABLA PRINCIPAL ENTIDAD (TITULOS)
-- -----------------------------------------------------------------------------

CREATE TABLE public.titulos (
    id_titulo SERIAL PRIMARY KEY,
    show_id_original CHARACTER VARYING(20) NOT NULL UNIQUE,
    titulo CHARACTER VARYING(255) NOT NULL,
    id_tipo_contenido INT NOT NULL REFERENCES public.tipos_contenido(id_tipo_contenido) ON DELETE RESTRICT,
    id_clasificacion INT REFERENCES public.clasificaciones(id_clasificacion) ON DELETE SET NULL,
    ano_lanzamiento SMALLINT CHECK ((ano_lanzamiento >= 1800) AND (ano_lanzamiento <= 2100)),
    fecha_adicion DATE,
    duracion_valor INT CHECK (duracion_valor >= 0),
    duracion_unidad CHARACTER VARYING(20) CHECK (((duracion_unidad)::text = ANY ((ARRAY['min'::character varying, 'Season'::character varying, 'Seasons'::character varying])::text[]))),
    descripcion TEXT
);
COMMENT ON TABLE public.titulos IS 'Tabla principal conteniendo la información atómica de películas y series';

-- -----------------------------------------------------------------------------
-- 3. TABLAS ASOCIATIVAS (RELACIONES N:M)
-- -----------------------------------------------------------------------------

CREATE TABLE public.titulo_genero (
    id_titulo INT NOT NULL REFERENCES public.titulos(id_titulo) ON DELETE CASCADE,
    id_genero INT NOT NULL REFERENCES public.generos(id_genero) ON DELETE CASCADE,
    CONSTRAINT pk_titulo_genero PRIMARY KEY (id_titulo, id_genero)
);

CREATE TABLE public.titulo_pais (
    id_titulo INT NOT NULL REFERENCES public.titulos(id_titulo) ON DELETE CASCADE,
    id_pais INT NOT NULL REFERENCES public.paises(id_pais) ON DELETE CASCADE,
    CONSTRAINT pk_titulo_pais PRIMARY KEY (id_titulo, id_pais)
);

CREATE TABLE public.titulo_participacion (
    id_titulo INT NOT NULL REFERENCES public.titulos(id_titulo) ON DELETE CASCADE,
    id_persona INT NOT NULL REFERENCES public.personas(id_persona) ON DELETE CASCADE,
    rol CHARACTER VARYING(20) NOT NULL,
    CONSTRAINT pk_titulo_participacion PRIMARY KEY (id_titulo, id_persona, rol),
    CONSTRAINT chk_rol_participacion CHECK (((rol)::text = ANY ((ARRAY['Director'::character varying, 'Cast'::character varying])::text[])))
);

